solution.solution.cpp:
#include <deque>
#include <functional>
#include <string>
#include <vector>

struct Change { std::string label; std::function<void()> apply; std::function<void()> revert; };

class UndoStack
{
public:
    explicit UndoStack(int limit) : m_limit{ limit < 1 ? 1 : limit } {}

    void push(Change c) { record({ c.label, { std::move(c) } }); }

    void pushGroup(const std::string& label, std::vector<Change> changes) { record({ label, std::move(changes) }); }

    bool undo()
    {
        if (m_undo.empty()) return false;
        Step s{ std::move(m_undo.back()) };
        m_undo.pop_back();
        for (auto it{ s.changes.rbegin() }; it != s.changes.rend(); ++it) if (it->revert) it->revert();
        m_redo.push_back(std::move(s));
        --m_position;
        return true;
    }

    bool redo()
    {
        if (m_redo.empty()) return false;
        Step s{ std::move(m_redo.back()) };
        m_redo.pop_back();
        for (auto& c : s.changes) if (c.apply) c.apply();
        m_undo.push_back(std::move(s));
        ++m_position;
        return true;
    }

    std::string undoLabel() const { return m_undo.empty() ? "" : "Undo " + m_undo.back().label; }
    std::string redoLabel() const { return m_redo.empty() ? "" : "Redo " + m_redo.back().label; }

    void markSaved() { m_saved = m_position; }
    bool dirty() const { return m_saved != m_position; }

private:
    struct Step { std::string label; std::vector<Change> changes; };

    void record(Step s)
    {
        // A saved point that only existed in the redo history can never be reached again.
        if (m_saved > m_position) m_saved = LOST;
        m_redo.clear();
        m_undo.push_back(std::move(s));
        ++m_position;
        if (static_cast<int>(m_undo.size()) > m_limit)
        {
            m_undo.pop_front();
            // positions count from the oldest kept step; dropping it moves everything down by one
            --m_position;
            if (m_saved != LOST) { if (m_saved == 0) m_saved = LOST; else --m_saved; }
        }
    }

    static constexpr long LOST = -1000000;
    int m_limit;
    std::deque<Step> m_undo;
    std::vector<Step> m_redo;
    long m_position{ 0 };     // number of steps in the undo history
    long m_saved{ 0 };
};

unitTests:
struct Doc { int value = 0; };
Change setTo(Doc& d, int before, int after, const char* label) { d.value = after; return { label, [&d, after] { d.value = after; }, [&d, before] { d.value = before; } }; }
TEST("undo and redo") {
    Doc d; UndoStack u{ 10 };
    u.push(setTo(d, 0, 5, "set 5")); u.push(setTo(d, 5, 9, "set 9"));
    CHECK_EQ(u.undoLabel(), std::string("Undo set 9")); CHECK(u.undo()); CHECK_EQ(d.value, 5);
    CHECK_EQ(u.redoLabel(), std::string("Redo set 9")); CHECK(u.redo()); CHECK_EQ(d.value, 9);
    CHECK(u.undo()); CHECK(u.undo()); CHECK_EQ(d.value, 0); CHECK(!u.undo()); CHECK_EQ(u.undoLabel(), std::string(""));
}
TEST("a new change clears redo") { Doc d; UndoStack u{ 10 }; u.push(setTo(d, 0, 1, "a")); u.undo(); u.push(setTo(d, 0, 2, "b")); CHECK(!u.redo()); CHECK_EQ(u.redoLabel(), std::string("")); }
TEST("groups revert in reverse") {
    std::string trace; UndoStack u{ 10 };
    u.pushGroup("delete 2", { { "x", [&] { trace += "A1"; }, [&] { trace += "R1"; } }, { "y", [&] { trace += "A2"; }, [&] { trace += "R2"; } } });
    CHECK_EQ(u.undoLabel(), std::string("Undo delete 2")); u.undo(); CHECK_EQ(trace, std::string("R2R1")); u.redo(); CHECK_EQ(trace, std::string("R2R1A1A2"));
}
TEST("limit drops the oldest") { Doc d; UndoStack u{ 2 }; u.push(setTo(d, 0, 1, "1")); u.push(setTo(d, 1, 2, "2")); u.push(setTo(d, 2, 3, "3")); CHECK(u.undo()); CHECK(u.undo()); CHECK(!u.undo()); CHECK_EQ(d.value, 1); }
TEST("saved and dirty") {
    Doc d; UndoStack u{ 10 }; CHECK(!u.dirty());
    u.push(setTo(d, 0, 1, "a")); CHECK(u.dirty()); u.markSaved(); CHECK(!u.dirty());
    u.push(setTo(d, 1, 2, "b")); CHECK(u.dirty()); u.undo(); CHECK(!u.dirty()); u.undo(); CHECK(u.dirty()); u.redo(); CHECK(!u.dirty());
}
TEST("saved point lost in redo") { Doc d; UndoStack u{ 10 }; u.push(setTo(d, 0, 1, "a")); u.markSaved(); u.undo(); u.push(setTo(d, 0, 7, "b")); CHECK(u.dirty()); u.undo(); CHECK(u.dirty()); }
TEST("saved point dropped by the limit") { Doc d; UndoStack u{ 1 }; u.markSaved(); u.push(setTo(d, 0, 1, "a")); u.push(setTo(d, 1, 2, "b")); u.undo(); CHECK(u.dirty()); }

